<button aria-label="القائمة السريعة" onClick="{{sxMenu}}" style="width: 44px; height: 44px; border-radius: 10px; border: 1px solid #3A3D44; background: transparent; color: #F5F5F2; display: flex; align-items: center; justify-content: center"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16"></path></svg></button>
