<button onClick="{{add}}" style="height: 48px; padding: 0 20px 0 22px; border-radius: 12px; border: none; background: {{accent}}; color: #141518; font-size: 16px; font-weight: 700; display: flex; align-items: center; gap: 8px"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" aria-hidden="true"><path d="M12 5v14M5 12h14"></path></svg>مزوّد جديد</button>
