<div style="display: flex; align-items: baseline; gap: 3px; direction: ltr; font-family: 'Poppins', sans-serif"><span style="font-weight: 700; font-size: 26px; letter-spacing: -0.5px">SX<span style="color: {{accent}}">.</span></span><span style="font-size: 12px; font-weight: 600; color: #9A9CA3">v1</span></div>
